#include <bits/stdc++.h>
using namespace std;
int main() {
    int r, c;
    cin >> r >> c;
    vector<string> g(r);
    for (auto &x : g) cin >> x;
    vector<int> d(r * c, -1);
    queue<int> q;
    if (g[0][0] == '.') { d[0] = 0; q.push(0); }
    int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int k = 0; k < 4; k++) {
             int x = u / c + dx[k], y = u % c + dy[k];
             if (x < 0 || y < 0 || x >= r || y >= c) continue;
             if (g[x][y] == '#' || d[x * c + y] != -1) continue;
             d[x * c + y] = d[u] + 1;
             q.push(x * c + y);
        }
    }
    cout << d[r * c - 1];
}

